/**
 * @name Race conditions in cachetools threading
 * @description Potential data races in cache operations with threading
 * @kind path-problem
 * @problem.severity warning
 * @id py/cachetools-data-race
 * @tags security
 *        external/cwe/cwe-362
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module RaceConditionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Look for threading operations
    source = API::moduleImport("threading").getMember(["Thread", "Lock", "RLock"]).getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for dictionary/list operations that modify shared state
    sink = API::builtin("dict").getMember(["__setitem__", "__delitem__", "pop", "clear", "update"]).getACall() or
    sink = API::builtin("list").getMember(["append", "extend", "insert", "remove", "pop", "clear"]).getACall() or
    sink = API::builtin("set").getMember(["add", "remove", "discard", "clear", "update"]).getACall()
  }
}

module RaceConditionFlow = TaintTracking::Global<RaceConditionConfig>;
import RaceConditionFlow::PathGraph

from RaceConditionFlow::PathNode source, RaceConditionFlow::PathNode sink
where RaceConditionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential data race from threading operation to shared data modification $@.", source.getNode(), "threading operation"
